const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `usage: prog [-h] --a A --b B --c C` (no trailing newline). */
export function formatUsage(prog, actions) {
  const parts = actions.map((action) => {
    const flag = action.optionStrings[0];
    const body = action.takesValue ? `${flag} ${action.metavar}` : flag;
    return action.required ? body : `[${body}]`;
