/** The single-line invocation shown in the options list, e.g. `-h, --help`. */
function formatInvocation(action) {
  if (!action.takesValue) return action.optionStrings.join(', ');
  return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
