 * Full `--help` output. The help column sits at
 * min(maxInvocationLength + indent + 2, 24), and an action with no help text
 * is emitted as a bare header line with no padding — which is why `--a A`
 * appears unpadded while `-h, --help` is padded out to the help column.
 */
export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(...invocations.map((s) => s.length)) + INDENT;
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - INDENT - 2;

  let out = `${formatUsage(prog, actions)}\n\noptions:\n`;

  actions.forEach((action, i) => {
    const invocation = invocations[i];
    if (action.help) {
      out += `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
    } else {
