    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.takesValue) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (token === '--') {
        // argparse only strips '--' while consuming a positional; with no
        // positionals declared it survives into the leftovers.
        extras.push(...argv.slice(i));
        break;
      }

      const optional = this.parseOptional(token);
      if (optional === null) {
        extras.push(token);
        continue;
      }

      const { action, sep, explicitArg } = optional;

      if (action === null) {
        extras.push(token);
        continue;
      }

      if (action.action === 'help') {
