/**
 * Resolve a token that starts with a prefix character.
 *
 * Returns null when argparse would treat the token as a positional (a bare
 * '-', a negative number, or anything containing a space), otherwise an
 * object whose `action` is null for an unrecognized option.
 *
 * `sep` records how a value was attached: '=' for `--opt=value`, '' for a
 * short option with its value concatenated (`-hx`), null when no value was
 * attached. argparse treats those two attachments differently for zero-
 * argument actions, so the distinction has to survive.
 */
parseOptional(token) {
  if (!token) return null;
  if (!token.startsWith('-')) return null;

  const exact = this.findByOptionString(token);
  if (exact) return { action: exact, optionString: token, sep: null, explicitArg: null };

  if (token.length === 1) return null; // a lone '-' is a positional

  if (token.includes('=')) {
    const eq = token.indexOf('=');
    const head = token.slice(0, eq);
    const tail = token.slice(eq + 1);
    const byHead = this.findByOptionString(head);
    if (byHead) return { action: byHead, optionString: head, sep: '=', explicitArg: tail };
  }

  const tuples = this.optionTuples(token);
  if (tuples.length > 1) {
    const names = tuples.map((t) => t.optionString).join(', ');
    this.error(`ambiguous option: ${token} could match ${names}`);
  }
  if (tuples.length === 1) return tuples[0];

  if (NEGATIVE_NUMBER.test(token)) return null; // no numeric-looking options here
  if (token.includes(' ')) return null;

  return { action: null, optionString: token, sep: null, explicitArg: null };
}

findByOptionString(name) {
  return this.actions.find((a) => a.optionStrings.includes(name)) ?? null;
}

/**
 * argparse._get_action_name(): every option string joined with '/'. This is
 * the spelling that appears in "argument -h/--help: ..." messages, and it is
 * independent of which spelling the user actually typed.
 */
static actionName(action) {
  return action.optionStrings.join('/');
}

/** Abbreviation matching for long options, e.g. '--he' -> '--help'. */
optionTuples(token) {
  const results = [];

  if (token.startsWith('--')) {
    let prefix = token;
    let explicitArg = null;
    if (token.includes('=')) {
      const eq = token.indexOf('=');
      prefix = token.slice(0, eq);
      explicitArg = token.slice(eq + 1);
    }
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith(prefix)) {
          results.push({ action, optionString, sep: explicitArg === null ? null : '=', explicitArg });
        }
      }
    }
  } else {
    // Single-dash tokens may be a short option with a concatenated value.
    const shortPrefix = token.slice(0, 2);
    const shortExplicit = token.slice(2);
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString === shortPrefix) {
          results.push({
            action,
            optionString,
            sep: shortExplicit ? '' : null,
            explicitArg: shortExplicit || null,
          });
        } else if (optionString.startsWith(token)) {
          results.push({ action, optionString, sep: null, explicitArg: null });
        }
      }
    }
  }

  return results;
}
